            "data": {
              "titleEn": "Sound Wave Frequency Calculation",
              "problemEn": "A sound wave has a frequency of 2 kHz and wavelength 35 cm. How long will it take to travel 1.5 km?",
              "steps": [
                {
                  "label": "Step 1: Convert units",
                  "content": "f = 2000 Hz, λ = 0.35 m, d = 1500 m."
                },
                {
                  "label": "Step 2: Calculate wave speed",
                  "content": "v = f × λ = 2000 × 0.35 = 700 m/s."
                },
                {
                  "label": "Step 3: Calculate time",
                  "content": "t = d / v = 1500 / 700 = 2.14 seconds."
                }
              ],
              "answer": "Time t = 2.14 seconds"
            }
